  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Approves a pending IPO application if the related customer is still eligible to apply for IPO.
   * This operation changes the application status to APPROVAL and triggers the delivery of
   * informational emails to the customer and the related company.
   * Algorithm:
   * 1. Check whether the current application status is PENDING.
   * 2. Check whether customer.isEligibleForIPO() is true.
   * 3. If either check fails, return false.
   * 4. Set status to APPROVAL.
   * 5. Create and store/send two informational Email objects:
   *    - one addressed to the customer,
   *    - one addressed to the company.
   * 6. Return true.
   * Related Features:
   * - status
   * - customer
   * - company
   * - share
   * - amountOfMoney
   * - emails
   * Related Classes: Customer, Company, Email, ApplicationStatus
   * Input:
   * - No explicit parameters.
   * - Uses the current Application instance state.
   * - The application must have a non-null customer and company reference.
   * Output:
   * - boolean: true if the application is successfully approved; otherwise false.
   * Pre-condition:
   * - The application must exist.
   * - The application status must be PENDING.
   * - The related customer must be eligible for IPO at approval time.
   * Post-condition:
   * - If approved successfully:
   *   - status becomes APPROVAL.
   *   - two informational emails are associated with the application.
   *   - the application remains linked to the same customer and company.
   * - If approval fails:
   *   - status remains unchanged.
   *   - no approval email is sent.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean approve()
  {
    if (getStatus() != ApplicationStatus.PENDING) {
      return false;
    }
    Customer customer = getCustomer();
    Company company = getCompany();
    if (customer == null || company == null || !customer.isEligibleForIPO()) {
      return false;
    }

    setStatus(ApplicationStatus.APPROVAL);

    Email customerEmail = new Email();
    customerEmail.setReceiver(customer.getEmail());
    customerEmail.setContent("Dear " + customer.getName() + " " + customer.getSurname()
        + ", your IPO application for " + company.getName()
        + " has been approved. Shares: " + getShare()
        + ", Amount: " + getAmountOfMoney() + ".");
    getEmails().add(customerEmail);

    Email companyEmail = new Email();
    companyEmail.setReceiver(company.getEmail());
    companyEmail.setContent("IPO application approved for customer " + customer.getName() + " "
        + customer.getSurname() + ". Shares: " + getShare()
        + ", Amount: " + getAmountOfMoney() + ".");
    getEmails().add(companyEmail);

    return true;
    
  }

